// Target: 0x0038F678 nslSetSoundEmitter__FUiUi
// Reference: NSL/PS2/nsl_ps2_emitter.cpp

typedef unsigned int nlUint32;
typedef nlUint32 nslSoundId;
typedef nlUint32 nslEmitterId;

template<class T>
class fifo_queue
{
  T *queue;
  short queue_max;
  short start;
  short end;
  short count;
public:
  short push(const T& index_to_add);
  short find(const T& index_to_find, short remove_flag);
};

struct nslSound
{
  bool isReady;
  bool used;
  bool inRange;
  bool isReallyReady;
  bool isPlaying;
  bool isReallyPlaying;
  bool looping;
  bool isQueuing;
  short left, right, old_left, old_right;
  nlUint32 gasInstanceId;
  int pauseCount;
  int dampenCount;
  nslSoundId myId;
  nlUint32 mySource;
  nslEmitterId myEmitter;
  float rawVolume, positionalVolume, angle, pitch, minDist, maxDist;
};

struct nslEmitter
{
  bool used;
  bool autoRelease;
  bool isALineEmitter;
  nslEmitterId myId;
  float startPosition[3];
  float endPosition[3];
  float position[3];
  fifo_queue<nslSoundId> emittedSounds;
};

struct nslSystem
{
  char pad0[0xc044];
  nslSound soundSlots[256];
  nslEmitter emitterSlots[256];
  char pad13c44[0x15850 - 0x13c44];
  int initialized;
  char pad15854[0x15880 - 0x15854];
  bool on;
};

extern nslSystem nsl;
extern void nslFatal(const char *format, ...);

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal("NSL NOT INITIALIZED");
}

inline void _nslCheckSoundIdValidity(nslSoundId checkId)
{
  nslSoundId checkSlot = (checkId & 0x000003FF);
  nslSoundId upCheckId = (checkId & 0xFFFFFC00);
  if (checkId == 0)
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(nsl.soundSlots[checkSlot].used))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkSlot < 256))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(checkId == nsl.soundSlots[checkSlot].myId))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (!(upCheckId > 0))
    nslFatal("Bad Sound ID 0x%x\n", checkId);
  if (checkSlot > 256)
    nslFatal("Bad Sound ID 0x%x SLOT NUMBER ABOVE SLOTS\n", checkId);
}

inline void _nslCheckEmitterIdValidity(nslEmitterId checkId)
{
  if (checkId == 0) return;
  nslEmitterId checkSlot = (checkId & 0x000003FF);
  nslEmitterId upCheckId = checkId & 0xFFFFFC00;
  if (!(checkId != 0))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (!(checkSlot < 256))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (!(checkId == nsl.emitterSlots[checkSlot].myId))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (!(upCheckId > 0))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (checkSlot > 256)
    nslFatal("Bad Sound ID 0x%x SLOT NUMBER ABOVE SLOTS\n", checkId);
}

void nslSetSoundEmitter( nslEmitterId soundEmitter, nslSoundId soundInstance )
{
  if (!nsl.on) return;
  _nslInitialized();
  _nslCheckEmitterIdValidity(soundEmitter);
  _nslCheckSoundIdValidity(soundInstance);

  if (nsl.soundSlots[(soundInstance&0x000003FF)].myEmitter != 0) 
  {
    nsl.emitterSlots[(nsl.soundSlots[(soundInstance&0x000003FF)].myEmitter&0x000003FF)].emittedSounds.find(soundInstance, true);
  }
  if (soundEmitter != 0)
    nsl.emitterSlots[(soundEmitter&0x000003FF)].emittedSounds.push(soundInstance);

  nsl.soundSlots[(soundInstance&0x000003FF)].myEmitter = soundEmitter;
}
